css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.cd-shipment-box-label,
.cd-shipment-box-label * {
  box-sizing: border-box;
}


/* =========================================================
   BASE
========================================================= */

.cd-shipment-box-label {
  position: relative;

  overflow: hidden;
  padding: 4mm;

  color: #111;
  background: #fff;

  font-family: "TH Sarabun Document", sans-serif;

  font-size: 5.46mm;

  line-height: 1.05;
}


/* =========================================================
   PAGE DIMENSIONS
   Both sizes are narrow enough to need a stacked (top/bottom)
   sender/recipient layout -- neither fits a side-by-side split.
========================================================= */

.cd-shipment-box-label.label-size-75x100 {
  width: 74mm;
  height: 99mm;
}

.cd-shipment-box-label.label-size-100x180 {
  width: 99mm;
  height: 179mm;
}


/* =========================================================
   HEADER
========================================================= */

.cd-shipment-box-label .label-header {
  position: relative;

  height: 16mm;

  border-bottom: 0.6mm solid #111;
}

.cd-shipment-box-label .company-logo {
  display: block;

  width: 40mm;
  height: 12mm;

  object-fit: contain;
  object-position: left center;
}

.cd-shipment-box-label .territory {
  position: absolute;
  top: 0;
  right: 0;

  max-width: 30mm;
  min-height: 10mm;

  padding: 1.6mm 2.4mm;

  overflow: hidden;

  color: #fff;
  background: #111;

  font-size: 5.8mm;

  font-weight: 700;
  line-height: 1;

  text-align: center;

  overflow-wrap: anywhere;
  word-break: break-word;
}

.cd-shipment-box-label.label-size-100x180 .company-logo {
  width: 46mm;
  height: 14mm;
}

.cd-shipment-box-label.label-size-100x180 .territory {
  max-width: 40mm;
  min-height: 12mm;

  font-size: 6.4mm;
}


/* =========================================================
   PARTY SECTION -- stacked sender/recipient for both sizes
========================================================= */

.cd-shipment-box-label .party-section {
  position: relative;

  display: block;

  width: 100%;

  overflow: hidden;

  border-bottom: 0.35mm solid #111;
}

.cd-shipment-box-label .party-panel {
  position: absolute;
  left: 0;

  width: 100%;
  min-width: 0;

  padding: 3mm 4mm 2mm;

  overflow: hidden;
}

.cd-shipment-box-label .sender-panel {
  top: 0;
}

.cd-shipment-box-label .recipient-panel {
  border-top: 0.35mm solid #111;
}

.cd-shipment-box-label.label-size-75x100 .party-section {
  height: 79mm;
}

.cd-shipment-box-label.label-size-75x100 .party-panel {
  height: 39.5mm;
}

.cd-shipment-box-label.label-size-75x100 .recipient-panel {
  top: 39.5mm;
}

.cd-shipment-box-label.label-size-100x180 .party-section {
  height: 159mm;
}

.cd-shipment-box-label.label-size-100x180 .party-panel {
  height: 79.5mm;
}

.cd-shipment-box-label.label-size-100x180 .recipient-panel {
  top: 79.5mm;
}


/* =========================================================
   TYPOGRAPHY
========================================================= */

.cd-shipment-box-label h1 {
  margin: 0 0 1.5mm;

  font-size: 7.02mm;

  font-weight: 700;
  line-height: 1;
}

.cd-shipment-box-label h1 span {
  font-size: 4.55mm;

  font-weight: 400;
}

.cd-shipment-box-label .party-name,
.cd-shipment-box-label .party-address,
.cd-shipment-box-label .party-phone {
  max-width: 100%;

  overflow: hidden;

  overflow-wrap: anywhere;
  word-break: break-word;
}


/* =========================================================
   NAME
   Matches the h1 ("Sender" / "Recipient" label) size, but not
   bold, so the customer/company name reads at the same scale
   without competing with the section heading.
========================================================= */

.cd-shipment-box-label .party-name {
  max-height: 16mm;

  margin-bottom: 1.5mm;

  font-size: 7.02mm;

  font-weight: 400;
  line-height: 1.05;
}


/* =========================================================
   ADDRESS
========================================================= */

.cd-shipment-box-label .party-address {
  font-size: 5.2mm;

  line-height: 1.04;

  white-space: pre-line;
}

.cd-shipment-box-label .party-address p {
  margin: 0;
}


/* =========================================================
   PHONE
========================================================= */

.cd-shipment-box-label .party-phone {
  padding-top: 1mm;

  font-size: 5.2mm;

  line-height: 1;

  white-space: normal;
}


/* =========================================================
   100 x 180 -- larger paper, larger type throughout
========================================================= */

.cd-shipment-box-label.label-size-100x180 h1 {
  font-size: 9.1mm;
}

.cd-shipment-box-label.label-size-100x180 h1 span {
  font-size: 5.9mm;
}

.cd-shipment-box-label.label-size-100x180 .party-name {
  font-size: 9.1mm;
}

.cd-shipment-box-label.label-size-100x180 .party-address {
  font-size: 6.7mm;
}

.cd-shipment-box-label.label-size-100x180 .party-phone {
  font-size: 6.7mm;
}

html:
{# Shipment Box Label — dynamic 75x100 / 100x180 mm #}

{{ register_print(doc) }}

{# ---------------------------------------------------------
   PRINT SIZE
   Comes from Print Settings sidebar
--------------------------------------------------------- #}

{% set shipment_label_size = print_settings.custom_shipment_label_size or "75 x 100 mm" %}
{% set normalized_label_size = shipment_label_size | lower | replace(" ", "") %}
{% set is_portrait = "100x180" in normalized_label_size %}

{# Important:
   Frappe PDF generator reads page-width/page-height from .print-format.
   Keep this dynamic block inside Jinja HTML.
#}
{% if is_portrait %}
<style>
@page {
  size: 100mm 180mm;
  margin: 0;
}

.print-format {
  page-width: 100mm;
  page-height: 180mm;

  margin: 0 !important;
  width: 99mm !important;
  height: 179mm !important;
  min-height: 179mm !important;
  max-height: 179mm !important;
  padding: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  box-sizing: border-box;
  width: 99mm !important;
  height: 179mm !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
}
</style>
{% else %}
<style>
@page {
  size: 75mm 100mm;
  margin: 0;
}

.print-format {
  page-width: 75mm;
  page-height: 100mm;

  margin: 0 !important;
  width: 74mm !important;
  height: 99mm !important;
  min-height: 99mm !important;
  max-height: 99mm !important;
  padding: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  box-sizing: border-box;
  width: 74mm !important;
  height: 99mm !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
}
</style>
{% endif %}


{# ---------------------------------------------------------
   SENDER
--------------------------------------------------------- #}

{% set sender_type = doc.pickup_from_type or "" %}

{% if sender_type == "Company" %}
  {% set sender_id = doc.pickup_company %}
  {% set sender_name = frappe.db.get_value("Company", sender_id, "company_name") or sender_id %}
{% elif sender_type == "Customer" %}
  {% set sender_id = doc.pickup_customer %}
  {% set sender_name = frappe.db.get_value("Customer", sender_id, "customer_name") or sender_id %}
{% elif sender_type == "Supplier" %}
  {% set sender_id = doc.pickup_supplier %}
  {% set sender_name = frappe.db.get_value("Supplier", sender_id, "supplier_name") or sender_id %}
{% else %}
  {% set sender_id = "" %}
  {% set sender_name = doc.pickup or "" %}
{% endif %}


{# ---------------------------------------------------------
   RECIPIENT
--------------------------------------------------------- #}

{% set recipient_type = doc.delivery_to_type or "" %}

{% if recipient_type == "Company" %}
  {% set recipient_id = doc.delivery_company %}
  {% set recipient_name = frappe.db.get_value("Company", recipient_id, "company_name") or recipient_id %}
{% elif recipient_type == "Customer" %}
  {% set recipient_id = doc.delivery_customer %}
  {% set recipient_name = frappe.db.get_value("Customer", recipient_id, "customer_name") or recipient_id %}
{% elif recipient_type == "Supplier" %}
  {% set recipient_id = doc.delivery_supplier %}
  {% set recipient_name = frappe.db.get_value("Supplier", recipient_id, "supplier_name") or recipient_id %}
{% else %}
  {% set recipient_id = "" %}
  {% set recipient_name = doc.delivery_to or "" %}
{% endif %}


{# ---------------------------------------------------------
   SENDER ADDRESS
--------------------------------------------------------- #}

{% set sender_address =
  (doc.pickup_address or "")
  | replace("<br />", "~#~")
  | replace("<br/>", "~#~")
  | replace("<br>", "~#~")
  | replace("</p>", "~#~")
  | replace("</div>", "~#~")
  | replace("</li>", "~#~")
  | striptags
  | replace("~#~", "\n")
  | trim
%}

{% set sender_contact_text =
  (doc.pickup_contact or "")
  | replace("<br />", "~#~")
  | replace("<br/>", "~#~")
  | replace("<br>", "~#~")
  | striptags
  | trim
%}

{% set sender_contact_lines = sender_contact_text.split("~#~") %}
{% set sender_contact_last = sender_contact_lines[-1] | trim if sender_contact_lines else "" %}
{% set sender_contact_digits = sender_contact_last | select("in", "0123456789") | list | length %}

{% set sender_snapshot_phone =
  sender_contact_last
  if sender_contact_last
     and "@" not in sender_contact_last
     and sender_contact_digits >= 6
  else ""
%}

{% set sender_mobile =
  frappe.db.get_value(
    "Contact",
    doc.pickup_contact_name,
    "mobile_no"
  ) if doc.pickup_contact_name else ""
%}

{% set sender_contact_phone =
  frappe.db.get_value(
    "Contact",
    doc.pickup_contact_name,
    "phone"
  ) if doc.pickup_contact_name else ""
%}

{% set sender_address_phone =
  frappe.db.get_value(
    "Address",
    doc.pickup_address_name,
    "phone"
  ) if doc.pickup_address_name else ""
%}

{% set sender_phone =
  sender_snapshot_phone
  or sender_mobile
  or sender_contact_phone
  or sender_address_phone
%}


{# ---------------------------------------------------------
   RECIPIENT ADDRESS
--------------------------------------------------------- #}

{% set recipient_address =
  (doc.delivery_address or "")
  | replace("<br />", "~#~")
  | replace("<br/>", "~#~")
  | replace("<br>", "~#~")
  | replace("</p>", "~#~")
  | replace("</div>", "~#~")
  | replace("</li>", "~#~")
  | striptags
  | replace("~#~", "\n")
  | trim
%}

{% set recipient_contact_text =
  (doc.delivery_contact or "")
  | replace("<br />", "~#~")
  | replace("<br/>", "~#~")
  | replace("<br>", "~#~")
  | striptags
  | trim
%}

{% set recipient_contact_lines = recipient_contact_text.split("~#~") %}
{% set recipient_contact_last = recipient_contact_lines[-1] | trim if recipient_contact_lines else "" %}
{% set recipient_contact_digits = recipient_contact_last | select("in", "0123456789") | list | length %}

{% set recipient_snapshot_phone =
  recipient_contact_last
  if recipient_contact_last
     and "@" not in recipient_contact_last
     and recipient_contact_digits >= 6
  else ""
%}

{% set recipient_mobile =
  frappe.db.get_value(
    "Contact",
    doc.delivery_contact_name,
    "mobile_no"
  ) if doc.delivery_contact_name else ""
%}

{% set recipient_contact_phone =
  frappe.db.get_value(
    "Contact",
    doc.delivery_contact_name,
    "phone"
  ) if doc.delivery_contact_name else ""
%}

{% set recipient_address_phone =
  frappe.db.get_value(
    "Address",
    doc.delivery_address_name,
    "phone"
  ) if doc.delivery_address_name else ""
%}

{% set recipient_phone =
  recipient_snapshot_phone
  or recipient_mobile
  or recipient_contact_phone
  or recipient_address_phone
%}


{# ---------------------------------------------------------
   TERRITORY
--------------------------------------------------------- #}

{% set recipient_territory =
  frappe.db.get_value(
    "Customer",
    recipient_id,
    "territory"
  )
  if recipient_type == "Customer" and recipient_id
  else ""
%}


{# ---------------------------------------------------------
   LABEL
--------------------------------------------------------- #}

<article
  class="
    cd-shipment-box-label
    {% if is_portrait %}
      label-size-100x180
    {% else %}
      label-size-75x100
    {% endif %}
  "
>

  <header class="label-header">

    <img
      class="company-logo"
      src="/assets/connect_diagnostics_core/images/cd_logo_v2.jpg"
      alt="Connect Diagnostics"
    >

    {% if recipient_territory %}
      <div class="territory">
        {{ recipient_territory | truncate(40, True, "…") }}
      </div>
    {% endif %}

  </header>


  <section class="party-section">

    <section class="party-panel sender-panel">

      <h1>
        ผู้ส่ง
        <span>Sender</span>
      </h1>

      <div class="party-name">
        {{ (sender_name or "") | truncate(80, True, "…") }}
      </div>

      <div class="party-address">
        {{ sender_address | truncate(150, True, "…") }}
      </div>

      {% if sender_phone %}
        <div class="party-phone">
          โทร/Tel. {{ sender_phone }}
        </div>
      {% endif %}

    </section>


    <section class="party-panel recipient-panel">

      <h1>
        ผู้รับ
        <span>Recipient</span>
      </h1>

      <div class="party-name">
        {{ (recipient_name or "") | truncate(80, True, "…") }}
      </div>

      <div class="party-address">
        {{ recipient_address | truncate(150, True, "…") }}
      </div>

      {% if recipient_phone %}
        <div class="party-phone">
          โทร/Tel. {{ recipient_phone }}
        </div>
      {% endif %}

    </section>

  </section>

</article>
